func TestInstallGitHook_ExternalBackend_SuccessPrintsExternalHint(t *testing.T) {
	repoDir, _ := initHooksTestRepo(t)

	entireDir := filepath.Join(repoDir, ".entire")
	if err := os.MkdirAll(entireDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(
		filepath.Join(entireDir, "settings.json"),
		[]byte(`{"enabled": true, "git_hooks": {"backend": "external", "external_dir": ".husky"}}`),
		0o644,
	); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(repoDir, ".husky"), 0o755); err != nil {
		t.Fatal(err)
	}

	// Capture stdout
	origStdout := os.Stdout
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stdout = w
	t.Cleanup(func() { os.Stdout = origStdout })

	ctx := context.Background()
	if _, err := InstallGitHook(ctx, false, false, false); err != nil {
		_ = w.Close()
		t.Fatalf("InstallGitHook() error = %v", err)
	}
	_ = w.Close()

	var sb strings.Builder
	buf := make([]byte, 4096)
	for {
		n, _ := r.Read(buf)
		if n == 0 {
			break
		}
		sb.Write(buf[:n])
	}
	out := sb.String()
	wantLine := "Git hooks: external (.husky)"
	if !strings.Contains(out, wantLine) {
		t.Errorf("stdout missing %q; got:\n%s", wantLine, out)
	}
	// Make sure direct-mode hint line is NOT printed
	directLine := "Installed git hooks"
	if strings.Contains(out, directLine) {
		t.Errorf("stdout should NOT contain direct-mode line %q in external mode; got:\n%s", directLine, out)
	}
}

